const (
	TransactionData_Normal          uint8 = 0
	TransactionData_Mismatch        uint8 = 1
	TransactionData_UseItem         uint8 = 2
	TransactionData_UseItemOnEntity uint8 = 3
	TransactionData_ReleaseItem     uint8 = 4
)

type TransactionData struct {
	tag   uint8
	value any
}

func (self TransactionData) Tag() uint8 {
	return self.tag
}

func (self TransactionData) Normal() string {
	if self.tag != TransactionData_Normal {
		panic("tag mismatch")
	}
	return self.value.(string)
}

func (self TransactionData) Mismatch() string {
	if self.tag != TransactionData_Mismatch {
		panic("tag mismatch")
	}
	return self.value.(string)
}

func (self TransactionData) UseItem() UseItemTransactionData {
	if self.tag != TransactionData_UseItem {
		panic("tag mismatch")
	}
	return self.value.(UseItemTransactionData)
}

func (self TransactionData) UseItemOnEntity() UseItemOnEntityTransactionData {
	if self.tag != TransactionData_UseItemOnEntity {
		panic("tag mismatch")
	}
	return self.value.(UseItemOnEntityTransactionData)
}

func (self TransactionData) ReleaseItem() ReleaseItemTransactionData {
	if self.tag != TransactionData_ReleaseItem {
		panic("tag mismatch")
	}
	return self.value.(ReleaseItemTransactionData)
}

func MakeTransactionDataNormal(value string) TransactionData {
	return TransactionData{TransactionData_Normal, value}
}
func MakeTransactionDataMismatch(value string) TransactionData {
	return TransactionData{TransactionData_Mismatch, value}
}
func MakeTransactionDataUseItem(value UseItemTransactionData) TransactionData {
	return TransactionData{TransactionData_UseItem, value}
}
func MakeTransactionDataUseItemOnEntity(value UseItemOnEntityTransactionData) TransactionData {
	return TransactionData{TransactionData_UseItemOnEntity, value}
}
func MakeTransactionDataReleaseItem(value ReleaseItemTransactionData) TransactionData {
	return TransactionData{TransactionData_ReleaseItem, value}
}

